from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(status="captured", amt="100.00", refunded="0.00"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0,refunded_amount=Decimal(refunded))

# rounding >2 decimals
p=mk(); process_refund_request(p,"49.999","u",T0); print("round:",p.refunded_amount)
# full refund sets status
p=mk(); process_refund_request(p,"100.00","u",T0); print("full:",p.refunded_amount,p.status)
# partial then full
p=mk(); process_refund_request(p,"40.00","u",T0); process_refund_request(p,"60.00","u",T0); print("partial+full:",p.refunded_amount,p.status)
# over refund
p=mk(refunded="90.00")
try: process_refund_request(p,"20.00","u",T0)
except BillingError as e: print("over:",e.code)
# wrong state
p=mk(status="authorized")
try: process_refund_request(p,"10.00","u",T0)
except BillingError as e: print("state:",e.code)
# non-positive
p=mk()
try: process_refund_request(p,"0","u",T0)
except BillingError as e: print("zero:",e.code)
# naive datetime
p=mk()
try: process_refund_request(p,"10.00","u",datetime(2026,1,1))
except BillingError as e: print("naive:",e.code)
# audit
print("audit:", audit.events("payment_refunded")[-1]["event"], audit.events("payment_refunded")[-1]["requested_by"])
EOF"}

